// Outgoing payment financial channel classification
const isBankEntry = (entry) => {
  if (!entry) return false
  if (entry.bank_account || entry.bank_account_name) return true
  const mode = (entry.payment_mode || '').trim().toLowerCase()
  return mode === 'bank transfer' || mode === 'card' || mode === 'cheque' || mode === 'online'
}

const isCashInHandEntry = (entry) => {
  if (!entry) return false
  if (entry.petty_cash_account || entry.petty_cash_account_name) return true
  const mode = (entry.payment_mode || '').trim().toLowerCase()
  return mode === 'petty cash' || mode === 'cash' || mode === 'self account' || !mode || mode === 'cash (general)' || mode === 'by hand'
}

