  // Match petty cash account for a user (by owner id, linked_user id, or username/firstname)
  const findUserPettyCashAccount = (accounts, userObj) => {
    if (!accounts || accounts.length === 0) return null
    if (!userObj) return null

    const userId = userObj.id ? String(userObj.id) : null
    const username = (userObj.username || '').toLowerCase().trim()
    const firstName = (userObj.first_name || '').toLowerCase().trim()

    // 1. By ID (owner / linked_user)
    if (userId) {
      const byId = accounts.find(a => String(a.owner || a.linked_user || '') === userId)
      if (byId) return byId
    }

    // 2. By name match - ONLY for non-admin users with specific names
    if (username && username !== 'admin') {
      const byName = accounts.find(a => {
        const accName = (a.name || '').toLowerCase()
        const holder = (a.holder_name || '').toLowerCase()
        return accName.includes(username) || holder.includes(username)
      })
      if (byName) return byName
    }

    if (firstName && firstName !== 'admin') {
      const byFirstName = accounts.find(a => {
        const accName = (a.name || '').toLowerCase()
        const holder = (a.holder_name || '').toLowerCase()
        return accName.includes(firstName) || holder.includes(firstName)
      })
      if (byFirstName) return byFirstName
    }

    // No account linked to this user - do NOT return another user's account
    return null
  }

  // Petty Cash accounts relevant to the currently logged in user
  const userPettyCashAccounts = useMemo(() => {
    if (!pettyCashAccounts || pettyCashAccounts.length === 0) return []
    if (!user || (!user.id && !user.username)) return []

    const userId = user.id ? String(user.id) : null
    const username = (user.username || '').toLowerCase().trim()
    const firstName = (user.first_name || '').toLowerCase().trim()

    // 1. By ID (owner / linked_user)
    if (userId) {
      const byId = pettyCashAccounts.filter(a => String(a.owner || a.linked_user || '') === userId)
      if (byId.length > 0) return byId
    }

    // 2. By Name - ONLY for non-admin users
    if (username && username !== 'admin') {
      const byName = pettyCashAccounts.filter(a => {
        const accName = (a.name || '').toLowerCase()
        const holder = (a.holder_name || '').toLowerCase()
        return accName.includes(username) || holder.includes(username)
      })
      if (byName.length > 0) return byName
    }

    if (firstName && firstName !== 'admin') {
      const byFirstName = pettyCashAccounts.filter(a => {
        const accName = (a.name || '').toLowerCase()
        const holder = (a.holder_name || '').toLowerCase()
        return accName.includes(firstName) || holder.includes(firstName)
      })
      if (byFirstName.length > 0) return byFirstName
    }

    // If user has no personal linked accounts, return empty list (do NOT return all accounts)
    return []
  }, [pettyCashAccounts, user])

