  // Delete book
  const handleDeleteBook = async (bookId) => {
    const choice = await showConfirm({
      title: 'Delete Cashbook?',
      text: 'Are you sure you want to move this book and all its entries to the Recycle Bin? They can be restored at any time.',
      confirmButtonText: 'Move to Recycle Bin',
      permanentCheckboxLabel: 'Delete permanently (cannot be undone)',
      allowPermanent: true,
      isDangerous: true
    })
    if (!choice) return
    const isPermanent = choice === 'permanent'
    try {
      await api.delete(`cashbooks/${bookId}/${isPermanent ? '?permanent=true' : ''}`)
      setIsBookModalOpen(false)
      setEditingBook(null)
      fetchBooks()
      fetchMonthEntries(monthYearView)
      showToast(isPermanent ? 'Cashbook permanently deleted' : 'Cashbook moved to Recycle Bin')
    } catch (err) {
      showError('Action Failed', 'Failed to delete cashbook')
    }
  }

  // Export CSV / Report
  const handleExportCSV = () => {
    if (!filteredEntries || filteredEntries.length === 0) {
      showWarning('No Entries', 'No entries to export')
      return
    }
    const headers = ['Date', 'Time', 'Remark', 'Category', 'Mode', 'Cash In (SAR)', 'Cash Out (SAR)', 'Balance (SAR)']
    const rows = filteredEntries.map(e => [
      e.date,
      e.time || '',
      `"${(e.remark || '').replace(/"/g, '""')}"`,
      `"${e.category || ''}"`,
      e.payment_mode || 'Cash',
      e.entry_type === 'in' ? e.amount : '',
      e.entry_type === 'out' ? e.amount : '',
      e.running_balance
    ])
    const csvContent = 'data:text/csv;charset=utf-8,' + [headers.join(','), ...rows.map(r => r.join(','))].join('\n')
    const encodedUri = encodeURI(csvContent)
    const link = document.createElement('a')
    link.setAttribute('href', encodedUri)
    link.setAttribute('download', `${selectedBook?.name || 'Cashbook'}_Report.csv`)
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)
  }

