  // Export Cashbook Ledger PDF (Server-side Universal PDF Generator)
  const handleExportCashbookPDF = async () => {
    const bookId = selectedBook?.id || (books.length > 0 ? books[0].id : null)
    if (!bookId) {
      showWarning('Select Cashbook', 'Please select a cashbook first.')
      return
    }
    try {
      setCashbookPdfLoading(true)
      const params = { cashbook: bookId }
      if (typeFilter !== 'all') params.entry_type = typeFilter
      if (categoryFilter !== 'All') params.category = categoryFilter
      if (modeFilter !== 'All') params.payment_mode = modeFilter
      if (searchQuery.trim()) params.search = searchQuery.trim()

      if (duration !== 'all') {
        const today = new Date()
        const todayStr = today.toISOString().split('T')[0]
        if (duration === 'today') {
          params.start_date = todayStr
          params.end_date = todayStr
        } else if (duration === 'yesterday') {
          const yesterday = new Date(today)
          yesterday.setDate(yesterday.getDate() - 1)
          params.start_date = yesterday.toISOString().split('T')[0]
          params.end_date = yesterday.toISOString().split('T')[0]
        } else if (duration === 'this_week') {
          const weekAgo = new Date(today)
          weekAgo.setDate(weekAgo.getDate() - 7)
          params.start_date = weekAgo.toISOString().split('T')[0]
          params.end_date = todayStr
        } else if (duration === 'this_month') {
          params.start_date = `${todayStr.substring(0, 7)}-01`
          params.end_date = todayStr
        }
      }

      const res = await api.get('cashbook-entries/ledger-pdf/', {
        params,
        responseType: 'blob'
      })
      const bookSlug = (selectedBook?.name || 'cashbook').toLowerCase().replace(/[^a-z0-9]/g, '_')
      handlePdfResponse(res, `cashbook_${bookSlug}_${new Date().toISOString().slice(0, 10)}.pdf`)
    } catch (err) {
      console.error('Failed to export cashbook PDF:', err)
      showError('Export Failed', 'Failed to generate cashbook PDF ledger from server.')
    } finally {
      setCashbookPdfLoading(false)
    }
  }

  // Export Bank Flow PDF (Server-side Universal PDF Generator)
  const handleExportBankFlowPDF = async () => {
    try {
      setBankFlowPdfLoading(true)
      const params = {}
      if (bankFlowBankId !== 'all') params.bank_account = bankFlowBankId
      if (bankFlowType !== 'all') params.flow_type = bankFlowType
      if (bankFlowSearch.trim()) params.search = bankFlowSearch.trim()

      if (bankFlowDuration !== 'all') {
        const today = new Date()
        const todayStr = today.toISOString().split('T')[0]
        if (bankFlowDuration === 'today') {
          params.start_date = todayStr
          params.end_date = todayStr
        } else if (bankFlowDuration === 'yesterday') {
          const yesterday = new Date(today)
          yesterday.setDate(yesterday.getDate() - 1)
          params.start_date = yesterday.toISOString().split('T')[0]
          params.end_date = yesterday.toISOString().split('T')[0]
        } else if (bankFlowDuration === 'this_week' || bankFlowDuration === '7d') {
          const d7 = new Date(today)
          d7.setDate(d7.getDate() - 7)
          params.start_date = d7.toISOString().split('T')[0]
          params.end_date = todayStr
        } else if (bankFlowDuration === '14d') {
          const d14 = new Date(today)
          d14.setDate(d14.getDate() - 14)
          params.start_date = d14.toISOString().split('T')[0]
          params.end_date = todayStr
        } else if (bankFlowDuration === '28d') {
          const d28 = new Date(today)
          d28.setDate(d28.getDate() - 28)
          params.start_date = d28.toISOString().split('T')[0]
          params.end_date = todayStr
        } else if (bankFlowDuration === 'this_month') {
          params.start_date = `${todayStr.substring(0, 7)}-01`
          params.end_date = todayStr
        }
      }

      const res = await api.get('cashbook-entries/bank-flow-pdf/', {
        params,
        responseType: 'blob'
      })
      handlePdfResponse(res, `cashbook_bank_flow_${new Date().toISOString().slice(0, 10)}.pdf`)
    } catch (err) {
      console.error('Failed to export bank flow PDF:', err)
      showError('Export Failed', 'Failed to generate bank flow PDF from server.')
    } finally {
      setBankFlowPdfLoading(false)
    }
  }

