                    width: '32px',
                    height: '32px',
                    borderRadius: '50%',
                    border: isDarkMode ? '1px solid #262626' : '1px solid #e8ecf5',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    background: isDarkMode ? '#171717' : '#ffffff',
