                                  background: entry.payment_mode === 'Self Account' ? '#f3e8ff' : entry.payment_mode === 'Petty Cash' ? '#fef3c7' : '#e0f2fe',
                                  color: entry.payment_mode === 'Self Account' ? '#7e22ce' : entry.payment_mode === 'Petty Cash' ? '#92400e' : '#0369a1',
                                  fontSize: '0.72rem',
                                  fontWeight: '700',
                                  padding: '3px 10px',
                                  borderRadius: '999px'
