                                  <span style={{ fontSize: '0.75rem', color: isDarkMode ? '#cbd5e1' : '#475569', marginLeft: '0.4rem', fontWeight: '500', display: 'inline-flex', alignItems: 'center', gap: '3px' }}>
                                    <User size={11} />
                                    <span>{entry.party_name}</span>
                                  </span>
